<?php
require_once __DIR__ . '/../../include/auth_admin.php';
$role = 'Admin'; $area = 'admin'; $activeMenu = 'status'; $pageTitle = 'Status Surat';
$q = trim((string)($_GET['q'] ?? '')); $like = '%' . $q . '%';
$typeFilter = trim((string)($_GET['jenis'] ?? ''));
if (!in_array($typeFilter, ['Masuk','Keluar'], true)) $typeFilter = '';
$statusFilter = trim((string)($_GET['status'] ?? ''));
$validStatuses = ['Diterima','Menunggu Disposisi','Dalam Proses','Selesai','Ditolak','Draft','Dibatalkan'];
if (!in_array($statusFilter, $validStatuses, true)) $statusFilter = '';
$page = max(1,(int)($_GET['page'] ?? 1)); $perPage=10;
$count = $conn->prepare("SELECT COUNT(*) AS total FROM surat WHERE (?='' OR jenis_surat=?) AND (?='' OR nomor_surat LIKE ? OR perihal LIKE ? OR pengirim LIKE ? OR tujuan LIKE ?) AND (?='' OR status=?)");
$count->bind_param('sssssssss',$typeFilter,$typeFilter,$q,$like,$like,$like,$like,$statusFilter,$statusFilter); $count->execute(); $total=(int)$count->get_result()->fetch_assoc()['total']; $count->close();
$totalPages=max(1,(int)ceil($total/$perPage)); $page=min($page,$totalPages); $offset=($page-1)*$perPage;
$stmt=$conn->prepare("SELECT s.*, u.nama AS pembuat FROM surat s JOIN users u ON u.id=s.created_by WHERE (?='' OR s.jenis_surat=?) AND (?='' OR s.nomor_surat LIKE ? OR s.perihal LIKE ? OR s.pengirim LIKE ? OR s.tujuan LIKE ?) AND (?='' OR s.status=?) ORDER BY s.updated_at DESC, s.id DESC LIMIT ? OFFSET ?");
$stmt->bind_param('sssssssssii',$typeFilter,$typeFilter,$q,$like,$like,$like,$like,$statusFilter,$statusFilter,$perPage,$offset);
$stmt->execute(); $rows=$stmt->get_result();
require __DIR__ . '/../../include/header.php';
?>
<div class="page-heading"><div><h1>Status Surat</h1><p>Pantau status terkini dan telusuri riwayat setiap surat.</p><div class="breadcrumbs"><a href="<?= BASE_URL ?>/<?= $area ?>/dashboard.php">Dashboard</a><span>›</span>Status Surat</div></div></div>
<div class="mini-stats"><div><span>Seluruh Surat</span><strong><?= number_format($total) ?></strong></div><div><span>Menunggu Disposisi</span><?php $n=$conn->query("SELECT COUNT(*) jumlah FROM surat WHERE status='Menunggu Disposisi'")->fetch_assoc(); ?><strong><?= number_format((int)$n['jumlah']) ?></strong></div><div><span>Dalam Proses</span><?php $n=$conn->query("SELECT COUNT(*) jumlah FROM surat WHERE status='Dalam Proses'")->fetch_assoc(); ?><strong><?= number_format((int)$n['jumlah']) ?></strong></div><div><span>Selesai</span><?php $n=$conn->query("SELECT COUNT(*) jumlah FROM surat WHERE status='Selesai'")->fetch_assoc(); ?><strong><?= number_format((int)$n['jumlah']) ?></strong></div></div>
<section class="panel filter-panel"><div class="panel-heading"><div><h2>Filter Status Surat</h2><p>Gunakan pencarian, jenis surat, atau status saat ini.</p></div></div><form class="filter-form status-filter" method="get"><label class="search-input"><span>⌕</span><input type="search" name="q" value="<?= htmlspecialchars($q, ENT_QUOTES, 'UTF-8') ?>" placeholder="Cari nomor surat atau perihal..."></label><select name="jenis"><option value="">Semua Jenis Surat</option><option value="Masuk" <?= $typeFilter==='Masuk'?'selected':'' ?>>Surat Masuk</option><option value="Keluar" <?= $typeFilter==='Keluar'?'selected':'' ?>>Surat Keluar</option></select><select name="status"><option value="">Semua Status</option><?php foreach ($validStatuses as $st): ?><option value="<?= htmlspecialchars($st, ENT_QUOTES, 'UTF-8') ?>" <?= $statusFilter===$st?'selected':'' ?>><?= htmlspecialchars($st, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><div class="filter-actions"><button class="button button-dark" type="submit">Cari</button><a class="button button-light" href="<?= BASE_URL ?>/<?= $area ?>/status_surat/index.php">Reset</a></div></form></section>
<section class="panel"><div class="panel-heading"><div><h2>Daftar Pemantauan Surat</h2><p>Menampilkan <?= $total ? $offset+1 : 0 ?>–<?= min($offset+$perPage,$total) ?> dari <?= number_format($total) ?> data.</p></div></div>
<?php if ($rows->num_rows > 0): ?><div class="table-wrap"><table><thead><tr><th>No.</th><th>Jenis Surat</th><th>Nomor Surat</th><th>Perihal</th><th>Status Saat Ini</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody><?php $no=$offset+1; while ($row=$rows->fetch_assoc()): ?><tr><td><?= $no++ ?></td><td><?= $row['jenis_surat']==='Masuk'?'Surat Masuk':'Surat Keluar' ?></td><td class="cell-strong"><?= htmlspecialchars($row['nomor_surat'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['perihal'], ENT_QUOTES, 'UTF-8') ?></td><td><span class="status-badge <?= $row['status']==='Selesai'?'status-done':($row['status']==='Dalam Proses'?'status-progress':(in_array($row['status'],['Ditolak','Dibatalkan'],true)?'status-rejected':'status-waiting')) ?>"><?= htmlspecialchars($row['status'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?= date('d-m-Y H:i',strtotime($row['updated_at'])) ?></td><td><a class="button-small" href="<?= BASE_URL ?>/<?= $area ?>/status_surat/detail.php?id=<?= (int)$row['id'] ?>"><?= $role==='Admin'?'Pantau / Ubah':'Lihat Riwayat' ?></a></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty-state">Surat tidak ditemukan untuk filter tersebut.</div><?php endif; ?>
<?php if ($totalPages>1): ?><nav class="pagination" aria-label="Paginasi"><?php for($p=1;$p<=$totalPages;$p++):$params=$_GET;$params['page']=$p; ?><a class="<?= $p===$page?'current':'' ?>" href="?<?= htmlspecialchars(http_build_query($params),ENT_QUOTES,'UTF-8') ?>"><?= $p ?></a><?php endfor; ?></nav><?php endif; ?></section>
<?php require __DIR__ . '/../../include/footer.php'; ?>
